 "content": "def transform(grid):
    """Project the colored seed pattern along the adjacent 5 rail."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    five = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    from collections import Counter
    row_counts = Counter(r for r, c in five)
    col_counts = Counter(c for r, c in five)

    # Horizontal separator: repeat the vertical seed pattern across it.
    if max(row_counts.values()) >= max(col_counts.values()):
        rail_row = max(row_counts, key=row_counts.get)
        rail_cols = [c for r, c in five if r == rail_row]
        left, right = min(rail_cols), max(rail_cols)
        for r in range(h):
            color = grid[r][left - 1] if left > 0 else 0
            if color not in (0, 5):
                for c in range(left, right + 1):
                    out[r][c] = color
    else:
        # Vertical separator: repeat the seed pattern to its right. The seed
        # consists of the nonzero rows touching the lower end of this rail.
        rail_col = max(col_counts, key=col_counts.get)
        rail_rows = [r for r, c in five if c == rail_col]
        top, bottom = min(rail_rows), max(rail_rows)
        seed_rows = [r for r in range(h)
                     if any(grid[r][c] not in (0, 5) for c in range(rail_col + 1, w))]
        if seed_rows:
            seed_rows.sort()
            for r in range(top, bottom + 1):
                source = seed_rows[(r - top) % len(seed_rows)]
                for c in range(rail_col + 1, w):
                    if grid[source][c] not in (0, 5):
                        out[r][c] = grid[source][c]
        # Also fill the horizontal arm from its left-side color strip.
        for r in range(h):
            color = grid[r][0]
            if color not in (0, 5):
                for c in range(1, rail_col):
                    out[r][c] = color
    return out

